import asyncio, os, json, zipfile, subprocess, time, re
from playwright.async_api import async_playwright
APP = 'file:///home/claude/outil/Atelier-etude.html'; SYN = '/home/claude/Synthese_DAP_S1_Introduction.pdf'; COURS = '/home/claude/outil/cours.pdf'
OUT = '/home/claude/outil/shots14'; os.makedirs(OUT, exist_ok=True)
