            await page.keyboard.press('Escape')
            await page.click('#annotBtn'); await page.click('#capBtn'); await page.wait_for_timeout(200)
            r = await ev('(() => { const b=document.querySelector(".page[data-n=\\"17\\"]").getBoundingClientRect(); return {x:b.left, y:Math.max(b.top,80)}; })()')
            await page.mouse.move(r['x'] + 80, r['y'] + 100); await page.mouse.down(); await page.mouse.move(r['x'] + 400, r['y'] + 260, steps=6); await page.mouse.up(); await page.wait_for_timeout(1500)
            await page.keyboard.press('Escape'); await page.wait_for_timeout(300)
            # --- plan du cours
