            ok('image référencée dans le texte', '](captures/p17-1.' in md)
            await page.click('#expBtn'); await page.click('#ddExport [data-x="claude"]'); await page.wait_for_timeout(1200)
            ok('deuxième envoi : « nouveautés » proposé et vide', 'Rien de nouveau' in await ev('document.getElementById("tcSum").textContent'))
