            await ctx2.set_offline(False)
            # mise à jour : nouvelle version publiée
            sw_path = '/home/claude/outil/web/sw.js'; orig = open(sw_path, encoding='utf-8').read()
            open(sw_path, 'w', encoding='utf-8').write(orig.replace("const CACHE = 'atelier-", "const CACHE = 'atelier-test-"))
